const D = { density:.5, energy:.6, hue:205, speed:1, scale:1, x:.5, y:.5, sheen:.6, spread:.6, style:'moonlit', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u=Math.min(width,height);
// water sheen field (broad area element)
const BW=Math.max(400,Math.min(700,Math.round(width/2.6))), BH=Math.max(140,Math.round(BW*height/width));
if(!S.g||S.bw!==BW||S.bh!==BH){ S.g=createGraphics(BW,BH); S.g.pixelDensity(1); S.bw=BW; S.bh=BH; }
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed;
  const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
  S.hoff=fr(1); S.drops=[]; S.next=0;
}
const sd=P.seed|0;
function hsh(ix,iy){ let h=(ix*374761393+iy*668265263+sd*2147483647)|0; h=(h^(h>>>13))*1274126177|0; return ((h^(h>>>16))>>>0)/4294967295; }
function vn(x,y){ const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy,uu=fx*fx*(3-2*fx),vv=fy*fy*(3-2*fy); const a=hsh(ix,iy),b=hsh(ix+1,iy),c=hsh(ix,iy+1),d=hsh(ix+1,iy+1); return a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv; }
function fbm(x,y){ return 0.6*vn(x,y)+0.3*vn(x*2.03+5.1,y*2.03-3.2)+0.15*vn(x*4.1-2.3,y*4.1+7.7); }
function frnd(){ S.next=(S.next*1103515245+12345)&0x7fffffff; return S.next/0x7fffffff; }

const t=K.t;
const style=P.style;
const wc = style==='pond'?[0.10,0.13,0.15] : style==='ink'?[0.02,0.02,0.03] : style==='oil'?[0.05,0.04,0.10] : [0.03,0.06,0.13];
const gl = style==='pond'?[0.7,0.75,0.8] : style==='ink'?[1,1,1] : style==='oil'?[1.0,0.7,1.0] : [0.75,0.85,1.0];
const sst=(0.15+P.sheen*0.7)*(0.7+K.intensity*0.4);
const gg=S.g; gg.loadPixels(); const px=gg.pixels;
for(let j=0;j<BH;j++){ const yy=j/BH;
  for(let i=0;i<BW;i++){ const xx=i/BW;
    // slow glinting sheen (like moonlight streaking on water) — perpetual drift
    const f=fbm(xx*3.0 + t*0.05, yy*5.0 - t*0.09 + S.hoff*6);
    const glint=Math.pow(Math.max(0,f-0.42)*1.9,2.2);
    let R=wc[0]+gl[0]*glint*sst, G=wc[1]+gl[1]*glint*sst, B=wc[2]+gl[2]*glint*sst;
    if(style==='oil'){ const irid=0.5+0.5*Math.sin(f*12+xx*6); R+=irid*glint*sst*0.3; B+=(1-irid)*glint*sst*0.3; }
    const o=4*(j*BW+i); px[o]=Math.min(255,R*255); px[o+1]=Math.min(255,G*255); px[o+2]=Math.min(255,B*255); px[o+3]=255;
  }}
gg.updatePixels();
push(); if(P.alpha<100) tint(0,0,100,P.alpha); image(gg,0,0,width,height); pop();

// --- spawn drops (rain) + big splash on pulse ---
const rate=(0.4+P.density*2.5)*(0.6+P.speed*0.6);
if(!S.acc) S.acc=0; S.acc+= rate*0.06;
while(S.acc>1){ S.acc-=1;
  const px0=(0.5+(P.x-0.5)*0.6) + (frnd()-0.5)*P.spread*1.4;
  const py0=(0.5+(P.y-0.5)*0.6) + (frnd()-0.5)*P.spread*1.0;
  S.drops.push({x:px0,y:py0,t0:t,big:0.5+frnd()*0.6});
}
if(S.lastPulse==null||K.beat<S.lastPulse) S.lastPulse=K.beat;
if(K.beat-S.lastPulse>=1){ S.lastPulse=Math.floor(K.beat);
  S.drops.push({x:0.3+frnd()*0.4,y:0.3+frnd()*0.4,t0:t,big:1.4+frnd()*0.6});
}
if(S.drops.length>60) S.drops.splice(0,S.drops.length-60);

// --- draw expanding concentric rings ---
push(); blendMode(ADD); noFill();
const life=2.4+P.scale*2.2, cspd=u*(0.10+P.scale*0.14);
for(let d=S.drops.length-1; d>=0; d--){ const dr=S.drops[d]; const age=t-dr.t0;
  if(age>life){ S.drops.splice(d,1); continue; }
  const cxp=dr.x*width, cyp=dr.y*height;
  const decay=1-age/life;
  for(let ring=0; ring<3; ring++){
    const rad=(age*cspd - ring*u*0.03*dr.big);
    if(rad<=0) continue;
    const amp=decay*Math.exp(-ring*0.5)*(0.5+P.energy*0.8)*dr.big;
    const w=Math.max(1, u*0.004*(0.5+ring*0.4));
    strokeWeight(w);
    const rh=(style==='oil')?(200+age*50)%360:P.hue%360;
    stroke(rh, style==='ink'?0:55, 100, Math.min(90, 60*amp));
    ellipse(cxp,cyp, rad*2, rad*2*0.9);
  }
}
blendMode(BLEND); pop();
